using System.Text.Json;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Xunit;

namespace MyApp.Evals.Tests;

public class QualityEvaluationTests
{
    private static readonly string GoldenPath =
        Path.Combine(AppContext.BaseDirectory, "Quality", "golden.json");

    private static readonly string RubricPath =
        Path.Combine(AppContext.BaseDirectory, "Quality", "rubric.md");

    public static IEnumerable<object[]> GoldenCases()
    {
        var json = File.ReadAllText(GoldenPath);
        var cases = JsonSerializer.Deserialize<List<GoldenCase>>(json,
            new JsonSerializerOptions { PropertyNameCaseInsensitive = true })!;

        foreach (var c in cases)
        {
            yield return new object[] { c.Id, c.UserMessage, c.ExpectedTraits };
        }
    }

    [Theory]
    [MemberData(nameof(GoldenCases))]
    public async Task EvalCase_MeetsExpectedTraits(string id, string userMessage, string[] expectedTraits)
    {
        Assert.NotNull(id);
        Assert.NotEmpty(userMessage);
        Assert.NotEmpty(expectedTraits);

        // Placeholder: replace with actual agent invocation and evaluation scoring.
        // The harness loads golden.json cases and validates responses against the rubric.
        var rubric = await File.ReadAllTextAsync(RubricPath);
        Assert.False(string.IsNullOrWhiteSpace(rubric), "Rubric must not be empty.");

        await Task.CompletedTask;
    }
}

public record GoldenCase
{
    public string Id { get; init; } = string.Empty;
    public string UserMessage { get; init; } = string.Empty;
    public string[] ExpectedTraits { get; init; } = Array.Empty<string>();
}

using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evals.Tests;

/// <summary>
/// Central configuration for evaluation runs. Extend this class to configure
/// the chat client, evaluation metrics, and reporting storage.
/// </summary>
public static class EvaluationConfiguration
{
    public static IEnumerable<IEvaluator> GetEvaluators()
    {
        yield return new CoherenceEvaluator();
        yield return new RelevanceEvaluator();
        yield return new GroundednessEvaluator();
        yield return new FluencyEvaluator();
    }
}

